def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if (r,c) in seen: continue
            color=grid[r][c]; q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                x,y=q.popleft(); cells.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=x+dx,y+dy
                    if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==color:
                        seen.add((a,b));q.append((a,b))
            if color != bg:
                r0=min(x for x,y in cells); r1=max(x for x,y in cells)
                c0=min(y for x,y in cells); c1=max(y for x,y in cells)
                shape=frozenset((x-r0,y-c0) for x,y in cells)
                comps.append((color,cells,(r0,c0),shape))
    # The object which is an isolated singleton specifies the replacement color;
    # recolor the other object with the same normalized shape.
    singletons=[obj for obj in comps if len(obj[1])==1]
    for color,cells,origin,shape in singletons:
        matches=[obj for obj in comps if obj is not (color,cells,origin,shape) and obj[3]==shape and len(obj[1])>1]
        # Tuple identity cannot be relied on after reconstruction; skip the singleton itself by cell count.
        matches=[obj for obj in comps if obj[3]==shape and len(obj[1])>1]
        if matches:
            target=matches[0]
            out=[row[:] for row in grid]
            for r,c in target[1]: out[r][c]=color
            return out
    return [row[:] for row in grid]

if __name__ == '__main__':
