 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and (a, b) not in seen and grid[a][b] == color:
                        seen.add((a, b))
                        q.append((a, b))
            if color != bg:
                r0 = min(x for x, y in cells)
                c0 = min(y for x, y in cells)
                shape = frozenset((x-r0, y-c0) for x, y in cells)
                comps.append({'color': color, 'cells': cells, 'shape': shape,
                              'origin': (r0, c0), 'size': len(cells)})
    color_counts = Counter(v for row in grid for v in row if v != bg)

    def contained(small, large):
        # Same orientation; does a translated copy of the entire small object occur in large?
        if len(small) > len(large):
            return False
        for ar, ac in large:
            for br, bc in small:
                dr, dc = ar-br, ac-bc
                if all((r+dr, c+dc) in large for r, c in small):
                    return True
        return False

    candidates = []
    for i, a in enumerate(comps):
        for j, b in enumerate(comps):
            if i == j or a['color'] == b['color']:
                continue
            # A is the object to recolor; B is a larger/equally-sized shape-template.
            if not contained(a['cells'], set(b['cells'])):
                continue
            if a['size'] == b['size'] and color_counts[b['color']] <= color_counts[a['color']]:
                continue
            # Prefer the largest matched target; among equal shapes, prefer the more
            # prevalent template color and the earlier (upper/left) source object.
            score = (a['size'], min(b['size'], 40), color_counts[b['color']], -b['origin'][0], -b['origin'][1])
            candidates.append((score, a, b))
    if not candidates:
        return [row[:] for row in grid]
    _, target, template = max(candidates, key=lambda x: x[0])
    out = [row[:] for row in grid]
    for r, c in target['cells']:
        out[r][c] = template['color']
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
