 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and (a, b) not in seen and grid[a][b] == color:
                        seen.add((a, b))
                        q.append((a, b))
            if color != bg:
                r0, c0 = min(x for x, y in cells), min(y for x, y in cells)
                shape = frozenset((x-r0, y-c0) for x, y in cells)
                comps.append({'color': color, 'cells': cells, 'shape': shape,
                              'origin': (r0, c0), 'size': len(cells)})

    # Find a component which is a complete translational sub-pattern of a larger
    # differently-colored component. The smaller matching object takes that color.
    def translated_subset(small, large):
        if len(small) >= len(large):
            return False
        for ar, ac in large:
            for br, bc in small:
                dr, dc = ar-br, ac-bc
                if all((r+dr, c+dc) in large for r, c in small):
                    return True
        return False

    candidates = []
    for a in comps:
        for b in comps:
            if a is b or a['color'] == b['color']:
                continue
            if translated_subset(set(a['cells']), set(b['cells'])):
                candidates.append((a['size'], -b['size'], -b['origin'][0], -b['origin'][1], a, b))
    if not candidates:
        return [row[:] for row in grid]
    _, _, _, _, target, template = max(candidates, key=lambda x: x[:4])
    out = [row[:] for row in grid]
    for r, c in target['cells']:
        out[r][c] = template['color']
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
