 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                x, y = q.popleft()
                cells.add((x, y))
                for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    a, b = x+dx, y+dy
                    if 0 <= a < h and 0 <= b < w and (a,b) not in seen and grid[a][b] == color:
                        seen.add((a,b)); q.append((a,b))
            if color != bg:
                objects.append((color, cells))

    # In these grids, a small object may be a proper translated sub-pattern
    # of a larger object of another color. Recolor that smaller copy as the
    # enclosing/matching larger object's color.
    matches = []
    for i, (small_color, small) in enumerate(objects):
        for j, (large_color, large) in enumerate(objects):
            if i == j or small_color == large_color or len(small) >= len(large):
                continue
            for sr, sc in small:
                found = False
                for lr, lc in large:
                    dr, dc = lr-sr, lc-sc
                    if all((r+dr, c+dc) in large for r,c in small):
                        matches.append((len(small), -len(large), i, j))
                        found = True
                        break
                if found:
                    break
    if not matches:
        return [row[:] for row in grid]
    _, _, i, j = max(matches)
    out = [row[:] for row in grid]
    color = objects[j][0]
    for r, c in objects[i][1]:
        out[r][c] = color
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
