        return [row[:] for row in grid]
    host = max(hosts, key=lambda i: runs[i])
    target = max(targets, key=lambda i: len(components[i][1]))
    out = [row[:] for row in grid]
    replacement = components[host][0]
    for r, c in components[target][1]:
