def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                x, y = q.popleft()
                cells.add((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and (a, b) not in seen and grid[a][b] == color:
                        seen.add((a, b))
                        q.append((a, b))
            r0, c0 = min(x for x, y in cells), min(y for x, y in cells)
            shape = frozenset((x-r0, y-c0) for x, y in cells)
            objects.append((color, cells, shape, r0, c0))
    pairs = []
    for i, a in enumerate(objects):
        for b in objects[i+1:]:
            if a[0] != b[0] and a[2] == b[2]:
                pairs.append((a,b))
    if not pairs:
        return [row[:] for row in grid]
    a,b = max(pairs, key=lambda p: (max(p[0][3],p[1][3]), max(p[0][4],p[1][4])))
    target, source = (a,b) if (a[3],a[4]) > (b[3],b[4]) else (b,a)
    out = [row[:] for row in grid]
    for r,c in target[1]:
        out[r][c] = source[0]
    return out
