 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen, objects = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q, cells = deque([(r, c)]), set()
            seen.add((r, c))
            while q:
                x, y = q.popleft()
                cells.add((x, y))
                for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    a, b = x+dx, y+dy
                    if 0 <= a < h and 0 <= b < w and (a,b) not in seen and grid[a][b] == color:
                        seen.add((a,b)); q.append((a,b))
            objects.append((color, cells))
    # A short object that is an exact translated subpattern of a larger,
    # unrelated-color shape is recolored to that host shape's color. Prefer
    # the shortest matching object when several incidental subpatterns exist.
    matches = []
    for i, (color, shape) in enumerate(objects):
        if len(shape) < 2:
            continue
        for host_color, host in objects:
            if host_color == color or len(host) <= len(shape):
                continue
            for sr, sc in shape:
                for hr, hc in host:
                    dr, dc = hr-sr, hc-sc
                    if all((r+dr,c+dc) in host for r,c in shape):
                        matches.append((len(shape), i, host_color))
                        break
                else:
                    continue
                break
    if not matches:
        return [row[:] for row in grid]
    _, idx, replacement = min(matches)
    out = [row[:] for row in grid]
    for r,c in objects[idx][1]:
        out[r][c] = replacement
    return out
