def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen, out = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                x, y = q.popleft()
                cells.add((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and (a, b) not in seen and grid[a][b] == color:
                        seen.add((a, b))
                        q.append((a, b))
            r0, c0 = min(x for x, y in cells), min(y for x, y in cells)
            r1, c1 = max(x for x, y in cells), max(y for x, y in cells)
            shape = frozenset((x-r0, y-c0) for x, y in cells)
            out.append({'color': color, 'cells': cells, 'shape': shape,
                        'box': (r1-r0+1, c1-c0+1), 'r0': r0, 'c0': c0})
    return out

def transform(grid):
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    objs = _components(grid, bg)
    candidates = []
    for i, big in enumerate(objs):
        for small in objs[i+1:]:
            if big['color'] == small['color']:
                continue
            # Does the smaller object's exact shape occur as a translated subset
            # of the larger object's occupied cells?
            if len(big['cells']) <= len(small['cells']):
                big, small = small, big
            bh, bw = big['box']
            sh, sw = small['box']
            if sh > bh or sw > bw:
                continue
            bigshape, smallshape = big['shape'], small['shape']
            offsets = [(dr, dc) for dr in range(bh-sh+1) for dc in range(bw-sw+1)
                       if all((dr+r, dc+c) in bigshape for r, c in smallshape)]
            if offsets:
                candidates.append((len(big['cells']), len(small['cells']), big, small))
    if not candidates:
        return [row[:] for row in grid]
    _, _, big, small = max(candidates, key=lambda x: (x[0], x[1]))
    out = [row[:] for row in grid]
    for r, c in big['cells']:
        out[r][c] = small['color']
    return out
"
}

